import React, {createContext,useContext,useEffect,useRef,useState} from 'react';
import {Routes,Route,Link,NavLink,useLocation,useNavigate,useParams,useSearchParams,Navigate} from 'react-router-dom';
import {ArrowUpRight,ArrowRight,ChevronDown,ChevronLeft,ChevronRight,Menu,X,Search,Heart,ShoppingBag,Plus,Minus,Phone,MapPin,Check,MessageCircle,SlidersHorizontal,Upload,MoveHorizontal} from 'lucide-react';
import {business,wa,media,services,products,faqs,testimonials,aboutOriginal,articles,type Service,type Product} from './data';
import './styles.css';
import './refinements.css';
import './motion.css';
import './premium.css';
import './experience.css';
import './hero-navbar.css';
import './insights.css';
import './gallery.css';
import './contact.css';
import './intro.css';
import {gallery, galleryCategories, galleryService, type GalleryItem} from './gallery';
import { InsightsIndex, InsightArticle, ServiceInsightLink } from './Insights';
import { applyPageMetadata } from './seo';
import { imageProps } from './image-delivery';
import { PremiumHome, PremiumCTA, PremiumProcess, QuickConsultation } from './premium';
import { Accordion, Intro, Modal, MotionEffects, NavigationDropdown } from './motion';
